package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.SignacMatrixIO;
import org.jlinalg.sequence.SignacNormalization;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Independent native RunTFIDF and FindTopFeatures capture; no R or SVD requirement. */
public final class SignacNormalizationCli {
    private SignacNormalizationCli() { }
    static final String ENGINE="native-Signac-normalization-development";
    static final String SCOPE="SOURCE_SCOPE: native sparse RunTFIDF methods1-4 and FindTopFeatures metadata on declared integer counts/identities, with explicit selection following the retained current1.17.1 assay-wrapper contract. Original source profiles share the retained tested arithmetic; whole historical Seurat/Signac assay wrappers are not executed. Normalization retains every input feature/cell and stored coordinate, including explicit zeros. Variable-feature selection is separate metadata and does not subset the normalized matrix. This does not run SVD, QC, motif, peak, differential or biological inference.";
    static final String ACTION="Read WARNINGS.md, analysis-status.json, diagnostics.json, feature-metadata.tsv, variable-features.tsv, effective-idf.tsv and the complete normalized matrix before downstream use. FAIL2 admits no result, including partial files: preserve the attempt, correct the named count/identity/IDF/selection/source/capacity cause and retry into NEW output paths. Native normalization needs Java only; it never installs software or requires R/MACS. Supplied IDF is already on the desired method scale and is not logged again. NaN stored results become zero as in the source; infinity is retained and must prevent downstream analyses requiring finite values. Empty variable-feature selection is not repaired; skip downstream LSI instead of relaxing the cutoff silently. VERIFY replays native arithmetic and selection but does not authenticate execution, biology or historical whole packages. The lsi workflow consumes original integer counts and performs its own normalization; do not feed normalized real-valued output as raw counts.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(out,"SignacNormalizationCli --request UTF8_JSON\nModes: NORMALIZE, TOP_FEATURES, VERIFY. Declare selection explicitly; relative paths resolve against the request directory. Use NEW outputs.\n"+SCOPE+"\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON or --help");Path path=Path.of(args[1]).toAbsolutePath().normalize();var raw=read(path);
            if("VERIFY".equals(raw.get("mode"))){keys(raw,Set.of("schema_version","mode","analysis"));if(integer(raw,"schema_version",0,1,1)!=1)throw new IOException("Require schema1");verify(resolve(path.getParent(),text(raw,"analysis")));emit(out,"Verified native normalization/count metadata/selection. "+ACTION);return 0;}
            var r=validate(raw);byte[] source=Files.readAllBytes(path);String sourceHash=SeuratDifferentialRuntime.sha(source);Path target=resolve(path.getParent(),text(r,"out"));int[] code={0};
            FollowupSupport.externalTransaction(Map.of("out",target.toString()),ENGINE,(stage,manifest)->{
                var status=new LinkedHashMap<String,Object>();status.put("status","FAIL2_NO_RESULT_ADMITTED");status.put("results_admitted",false);List<String>warnings=new ArrayList<>(List.of(SCOPE));
                try{
                    if(!FollowupSupport.hash(path).equals(sourceHash))throw new IOException("Normalization request changed before capture");Files.write(stage.resolve("source-request.json"),source,StandardOpenOption.CREATE_NEW);var captured=captured(raw);var inputPins=capture(raw,captured,path.getParent(),stage,value(r,"maximum_input_bytes"));json(stage.resolve("request.json"),captured);var effective=validate(captured);json(stage.resolve("effective-request.json"),effective);sources(stage,false);warnings.addAll(calculate(stage,effective,false));
                    for(var e:inputPins.entrySet())if(!FollowupSupport.hash(stage.resolve(e.getKey())).equals(e.getValue()))throw new IOException("Captured normalization input changed");sources(stage,true);capacity(stage,value(effective,"maximum_output_bytes"));manifest.put("source_request_sha256",sourceHash);manifest.put("captured_input_sha256",inputPins);status.put("status","completed-with-warnings");status.put("results_admitted",true);
                    json(stage.resolve("COMPLETED.json"),Map.of("engine",ENGINE,"status","completed-native-normalization","results_admitted",true,"native_arithmetic_replay",true,"execution_authentication",false));
                }catch(Exception failure){code[0]=2;status.put("status","FAIL2_NO_RESULT_ADMITTED");status.put("results_admitted",false);status.put("error",failure.toString());warnings.add("FAIL2: "+failure+". Retained partial files are not admitted results.");}
                catch(OutOfMemoryError failure){code[0]=2;status.put("status","FAIL2_NO_RESULT_ADMITTED");status.put("results_admitted",false);status.put("error","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; use justified explicit capacities and heap, then retry into NEW paths.");}
                if(code[0]!=0&&Files.exists(stage.resolve("COMPLETED.json")))json(stage.resolve("COMPLETED.json"),Map.of("status",status.get("status"),"results_admitted",false));status.put("required_action",ACTION);json(stage.resolve("analysis-status.json"),status);Files.writeString(stage.resolve("WARNINGS.md"),warningText(status.get("status").toString(),warnings),StandardCharsets.UTF_8);manifest.put("engine",ENGINE);manifest.put("analysis_status",status.get("status"));manifest.put("results_admitted",status.get("results_admitted"));manifest.put("scope",SCOPE);manifest.put("native_arithmetic_replay",true);manifest.put("execution_authentication",false);manifest.put("historical_whole_packages",false);json(stage.resolve("manifest.json"),manifest);
            });SignacPeaksCli.seal(target);if(code[0]==0)try{verify(target);}catch(Exception failure){code[0]=2;reject(target,failure);}
            emit(code[0]==0?out:err,(code[0]==0?"Completed native normalization: ":"FAIL2 — NO NORMALIZATION RESULT ADMITTED: ")+target);if(code[0]!=0)emit(err,"Cause: "+read(target.resolve("analysis-status.json")).get("error"));emit(err,"WARNINGS / REQUIRED ACTION: "+target.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        }catch(OutOfMemoryError failure){emit(err,"FAIL2 — NO NORMALIZATION RESULT ADMITTED: Java heap exhausted. "+ACTION);return 2;}
        catch(Exception failure){emit(err,"FAIL2 — NO NORMALIZATION RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    static Map<String,Object> validate(Map<String,Object> raw)throws IOException{
        keys(raw,Set.of("schema_version","mode","source_profile","counts","features","cells","idf","selection","existing_features","tfidf_method","scale_factor","out","maximum_features","maximum_cells","maximum_entries","maximum_input_bytes","maximum_output_bytes","maximum_line_characters"));
        if(integer(raw,"schema_version",0,1,1)!=1)throw new IOException("Require schema1");var r=new LinkedHashMap<String,Object>(raw);String mode=choice(raw,"mode","",Set.of("NORMALIZE","TOP_FEATURES"));r.put("mode",mode);for(String key:List.of("counts","features","cells","out"))text(raw,key);r.put("source_profile",choice(raw,"source_profile","",Set.of("Signac-1.6.0","Signac-1.7.0","Signac-1.9.0","Signac-1.14.0","Signac-1.17.1")));
        var selection=object(raw.get("selection"),"explicit selection");keys(selection,Set.of("kind","value"));String kind=choice(selection,"kind","",Set.of("ALL","COUNT","PERCENTILE","KEEP_EXISTING"));double cutoff=0;if(Set.of("COUNT","PERCENTILE").contains(kind)){if(!selection.containsKey("value"))throw new IOException("Declare count/percentile cutoff explicitly");cutoff=real(selection,"value",0,0,kind.equals("PERCENTILE")?100:9007199254740991.0,true);}else if(selection.containsKey("value")&&real(selection,"value",0,0,0,true)!=0)throw new IOException("Unused nonzero cutoff");r.put("selection",Map.of("kind",kind,"value",cutoff));
        if(kind.equals("KEEP_EXISTING")!=raw.containsKey("existing_features"))throw new IOException("existing_features is required only for KEEP_EXISTING");if(raw.containsKey("existing_features"))text(raw,"existing_features");
        if(mode.equals("NORMALIZE")){r.put("tfidf_method",integer(raw,"tfidf_method",1,1,4));r.put("scale_factor",real(raw,"scale_factor",10000,0,Double.MAX_VALUE,false));if(raw.containsKey("idf"))text(raw,"idf");}
        else if(raw.containsKey("tfidf_method")||raw.containsKey("scale_factor")||raw.containsKey("idf"))throw new IOException("TOP_FEATURES refuses unused normalization options");
        r.put("maximum_features",integer(raw,"maximum_features",2000000,1,2000000));r.put("maximum_cells",integer(raw,"maximum_cells",2000000,1,2000000));r.put("maximum_entries",integer(raw,"maximum_entries",2000000,0,20000000));r.put("maximum_input_bytes",integer(raw,"maximum_input_bytes",1000000000,1,1000000000000L));r.put("maximum_output_bytes",integer(raw,"maximum_output_bytes",2000000000,1,1000000000000L));r.put("maximum_line_characters",integer(raw,"maximum_line_characters",16384,4096,1000000));return r;
    }
    static long value(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}
    private static final Map<String,String> INPUTS=Map.of("counts","inputs/counts.mtx","features","inputs/features.tsv","cells","inputs/cells.tsv","idf","inputs/idf.tsv","existing_features","inputs/existing.tsv");
    private static Map<String,Object> captured(Map<String,Object> raw){var r=new LinkedHashMap<String,Object>(raw);r.put("out",".");for(var e:INPUTS.entrySet())if(raw.containsKey(e.getKey()))r.put(e.getKey(),e.getValue());return r;}
    private static Map<String,String> capture(Map<String,Object> raw,Map<String,Object> captured,Path parent,Path root,long cap)throws IOException{
        Files.createDirectory(root.resolve("inputs"));Map<String,String> pins=new TreeMap<>();long total=0;for(var e:INPUTS.entrySet())if(raw.containsKey(e.getKey())){Path input=resolve(parent,text(raw,e.getKey()));String name=text(captured,e.getKey());if(!Files.isRegularFile(input,LinkOption.NOFOLLOW_LINKS)||Files.size(input)>cap-total)throw new IOException("Input unavailable, linked or exceeds aggregate input capacity: "+input);String before=FollowupSupport.hash(input);try(var in=Files.newInputStream(input);var out=Files.newOutputStream(root.resolve(name),StandardOpenOption.CREATE_NEW)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0){check();if(n>cap-total)throw new IOException("Captured input capacity exceeded");out.write(b,0,n);total+=n;}}if(!before.equals(FollowupSupport.hash(input))||!before.equals(FollowupSupport.hash(root.resolve(name))))throw new IOException("Normalization input changed during capture");pins.put(name,before);}return pins;
    }
    private static List<String> calculate(Path root,Map<String,Object> r,boolean compare)throws IOException{
        var limits=new SignacMatrixIO.Limits((int)value(r,"maximum_features"),(int)value(r,"maximum_cells"),(int)value(r,"maximum_entries"),value(r,"maximum_input_bytes"),(int)value(r,"maximum_line_characters"));var intake=SignacMatrixIO.readCounts(root.resolve(text(r,"counts")),root.resolve(text(r,"features")),root.resolve(text(r,"cells")),limits,()->Thread.currentThread().isInterrupted());var counts=intake.counts();var s=object(r.get("selection"),"selection");var cutoff=new SignacNormalization.Cutoff(SignacNormalization.CutoffKind.valueOf(text(s,"kind")),((Number)s.get("value")).doubleValue());List<String> existing=null;
        if(r.containsKey("existing_features")){existing=new ArrayList<>();try(var in=SeuratDifferentialInputs.reader(root.resolve(text(r,"existing_features")))){String line;while((line=SeuratDifferentialInputs.line(in))!=null){check();if(existing.size()>=value(r,"maximum_features"))throw new IOException("Existing variable-feature population exceeds capacity");existing.add(line);}}}
        var top=SignacNormalization.findTopFeatures(counts,cutoff,existing,()->Thread.currentThread().isInterrupted());var selected=new HashSet<>(top.selected());List<String>warnings=new ArrayList<>();warnings.add("RAW_COUNT_DOMAIN: finite nonnegative integer MatrixMarket counts, exact explicit identities and totals within2^53-1 are required. Duplicate coordinates are coalesced by exact addition; explicit zero coordinates remain stored. Fractional, TPM/log/residual input and silent identifier repair are not admitted.");if(intake.duplicateCoordinates()>0)warnings.add("DUPLICATE_MATRIX_COORDINATES: "+intake.duplicateCoordinates()+" duplicate coordinates were coalesced explicitly; inspect raw input and diagnostics.");if(top.selected().isEmpty())warnings.add("EMPTY_VARIABLE_FEATURE_SET: the declared source cutoff/KEEP_EXISTING population selects no features. No cutoff was relaxed; skip downstream LSI requiring features.");
        Budget budget=new Budget(root,value(r,"maximum_output_bytes"),compare);
        try(var t=new Table(root.resolve("feature-metadata.tsv"),compare,budget)){t.row("feature","original_index","total_count","percentile","selected");for(var f:top.metadata())t.row(f.id(),Integer.toString(f.originalIndex()+1),Long.toString(f.count()),number(f.percentile()),Boolean.toString(selected.contains(f.id())));}
        try(var t=new Table(root.resolve("variable-features.tsv"),compare,budget)){for(String id:top.selected())t.line(id+"\n");}
        double[] idf=null;if(r.containsKey("idf")){idf=new double[counts.features().size()];try(var in=SeuratDifferentialInputs.reader(root.resolve(text(r,"idf")))){if(!"feature\tidf".equals(SeuratDifferentialInputs.line(in)))throw new IOException("Require supplied IDF header feature<TAB>idf");for(int i=0;i<idf.length;i++){check();String line=SeuratDifferentialInputs.line(in);if(line==null)throw new IOException("Incomplete supplied IDF");String[] f=line.split("\t",-1);if(f.length!=2||!f[0].equals(counts.features().get(i)))throw new IOException("Supplied IDF must cover exact full feature identity/order; no reordering");try{idf[i]=Double.parseDouble(f[1]);}catch(NumberFormatException failure){throw new IOException("Invalid supplied IDF",failure);}}if(SeuratDifferentialInputs.line(in)!=null)throw new IOException("Extra supplied IDF rows");}}
        boolean finite=true;if(r.get("mode").equals("NORMALIZE")){
            var normalization=SignacNormalization.runTfidf(counts,SignacNormalization.Method.values()[(int)value(r,"tfidf_method")-1],((Number)r.get("scale_factor")).doubleValue(),idf,()->Thread.currentThread().isInterrupted());for(var w:normalization.warnings())warnings.add(w.code()+": "+w.message()+" Required action: "+w.requiredAction());var matrix=normalization.matrix();double[] values=matrix.values(),effective=normalization.effectiveIdf();int[] p=matrix.columnPointers(),rows=matrix.rowIndices();
            try(var t=new Table(root.resolve("normalized.mtx"),compare,budget)){t.line("%%MatrixMarket matrix coordinate real general\n");t.line("% Native RunTFIDF; every input identity and stored coordinate retained\n");t.line(matrix.features().size()+" "+matrix.cells().size()+" "+values.length+"\n");for(int cell=0;cell<matrix.cells().size();cell++)for(int k=p[cell];k<p[cell+1];k++){t.line((rows[k]+1)+" "+(cell+1)+" "+number(values[k])+"\n");finite&=Double.isFinite(values[k]);}}
            try(var t=new Table(root.resolve("effective-idf.tsv"),compare,budget)){t.row("feature","idf");for(int i=0;i<effective.length;i++)t.row(counts.features().get(i),number(effective[i]));}
            warnings.add("IDF_AND_SCALE: supplied IDF is already on the desired method scale and is not logged again. Computed IDF uses number_of_cells/total_feature_counts, not prevalence. Scale affects methods1/3 only. Full normalization precedes separate variable-feature selection; the normalized matrix is never subset here.");
        }
        for(var ids:Map.of("features.tsv",counts.features(),"cells.tsv",counts.cells()).entrySet())try(var t=new Table(root.resolve(ids.getKey()),compare,budget)){for(String id:ids.getValue())t.line(id+"\n");}
        Map<String,Object> diagnostics=new LinkedHashMap<>();diagnostics.put("features",counts.features().size());diagnostics.put("cells",counts.cells().size());diagnostics.put("input_entries",intake.inputEntries());diagnostics.put("duplicate_coordinates_coalesced",intake.duplicateCoordinates());diagnostics.put("explicit_zero_input_entries",intake.explicitZeroEntries());diagnostics.put("stored_coordinates",counts.values().length);diagnostics.put("selected_features",top.selected().size());diagnostics.put("normalized_values_finite",finite);diagnostics.put("mode",r.get("mode"));diagnostics.put("source_profile",r.get("source_profile"));diagnostics.put("feature_selection_contract","1.17.1-package-assay-wrapper");diagnostics.put("native_arithmetic_replay",true);diagnostics.put("execution_authentication",false);diagnostics.put("warnings",warnings);
        if(compare){if(!same(diagnostics,read(root.resolve("diagnostics.json"),64000000)))throw new IOException("Native normalization diagnostics differ");}else json(root.resolve("diagnostics.json"),diagnostics);return warnings;
    }
    static void verify(Path root)throws IOException{
        root=root.toAbsolutePath().normalize();var seal=read(root.resolve("capture-files.json"),16000000);keys(seal,Set.of("schema_version","authentication","files","directories"));if(integer(seal,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(seal.get("authentication")))throw new IOException("Invalid normalization seal");var actual=SeuratDifferentialRuntime.footprint(root);actual.remove("capture-files.json");var pins=object(seal.get("files"),"file hashes");if(!actual.keySet().equals(pins.keySet()))throw new IOException("Normalization member population differs");for(var e:pins.entrySet())if(!FollowupSupport.hash(root.resolve(e.getKey())).equals(e.getValue()))throw new IOException("Normalization capture hash mismatch");
        var state=read(root.resolve("analysis-status.json"));var manifest=read(root.resolve("manifest.json"));if(!"completed-with-warnings".equals(state.get("status"))||!Boolean.TRUE.equals(state.get("results_admitted"))||!ENGINE.equals(manifest.get("engine"))||!state.get("status").equals(manifest.get("analysis_status"))||!Boolean.TRUE.equals(manifest.get("results_admitted"))||!SCOPE.equals(manifest.get("scope"))||!ACTION.equals(state.get("required_action"))||!Boolean.TRUE.equals(manifest.get("native_arithmetic_replay"))||!Boolean.FALSE.equals(manifest.get("execution_authentication"))||!Boolean.FALSE.equals(manifest.get("historical_whole_packages")))throw new IOException("Failed/skipped/unsupported normalization capture is not admitted");
        var original=read(root.resolve("source-request.json"));validate(original);if(!FollowupSupport.hash(root.resolve("source-request.json")).equals(manifest.get("source_request_sha256")))throw new IOException("Original normalization request differs");var request=read(root.resolve("request.json"));if(!same(captured(original),request))throw new IOException("Captured normalization parameters/identity population differ");var r=validate(request);if(!same(r,read(root.resolve("effective-request.json"))))throw new IOException("Effective normalization parameters differ");Set<String> names=new HashSet<>();for(var e:INPUTS.entrySet())if(r.containsKey(e.getKey()))names.add(text(r,e.getKey()));var input=object(manifest.get("captured_input_sha256"),"input hashes");if(!names.equals(input.keySet()))throw new IOException("Original normalization input population differs");for(String name:names)if(!FollowupSupport.hash(root.resolve(name)).equals(input.get(name)))throw new IOException("Original normalization input binding differs");sources(root,true);capacity(root,value(r,"maximum_output_bytes"));var warnings=new ArrayList<>(List.of(SCOPE));warnings.addAll(calculate(root,r,true));if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText("completed-with-warnings",warnings)))throw new IOException("Normalization warnings/actions differ");
        var completed=read(root.resolve("COMPLETED.json"));if(!ENGINE.equals(completed.get("engine"))||!"completed-native-normalization".equals(completed.get("status"))||!Boolean.TRUE.equals(completed.get("results_admitted"))||!Boolean.TRUE.equals(completed.get("native_arithmetic_replay"))||!Boolean.FALSE.equals(completed.get("execution_authentication")))throw new IOException("Unsupported normalization completion claim");
        names.addAll(List.of("source-request.json","request.json","effective-request.json","analysis-status.json","manifest.json","manifest.yaml","COMPLETED.json","capture-files.json","WARNINGS.md","diagnostics.json","feature-metadata.tsv","variable-features.tsv","features.tsv","cells.tsv","source/SOURCE-PROFILES.json"));if(r.get("mode").equals("NORMALIZE"))names.addAll(List.of("normalized.mtx","effective-idf.tsv"));for(String n:object(profile().get("files"),"source pins").keySet())names.add("source/"+n);var withSeal=new HashSet<>(actual.keySet());withSeal.add("capture-files.json");if(!names.equals(withSeal))throw new IOException("Unexpected/missing normalization member");List<String> dirs;try(var paths=Files.walk(root)){Path base=root;dirs=paths.filter(p->!p.equals(base)&&Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).map(p->base.relativize(p).toString().replace('\\','/')).sorted().toList();}if(!dirs.equals(List.of("inputs","source"))||!dirs.equals(strings(seal.get("directories"),"directories",1,100)))throw new IOException("Unexpected normalization directory");
        LoaderOptions options=new LoaderOptions();options.setAllowDuplicateKeys(false);options.setMaxAliasesForCollections(0);options.setCodePointLimit(16000000);if(Files.size(root.resolve("manifest.yaml"))>16000000)throw new IOException("Generic manifest exceeds capacity");Map<String,Object> yaml;try(var in=Files.newBufferedReader(root.resolve("manifest.yaml"),StandardCharsets.UTF_8)){yaml=object(new Yaml(new SafeConstructor(options)).load(in),"generic manifest");}for(var e:manifest.entrySet())if(!same(e.getValue(),yaml.get(e.getKey())))throw new IOException("Generic/native normalization manifest differs");var expected=new TreeMap<String,Object>(pins);expected.remove("manifest.yaml");var normalized=new TreeMap<String,Object>();for(var e:object(yaml.get("output_sha256"),"generic output hashes").entrySet())if(normalized.put(e.getKey().replace('\\','/'),e.getValue())!=null)throw new IOException("Ambiguous generic output path transport");if(!same(expected,normalized))throw new IOException("Generic normalization output hashes/population differ");
    }
    private static byte[] resource(String name)throws IOException{try(var in=SignacNormalizationCli.class.getResourceAsStream("/org/jlinalg/omics/signac-normalize/"+name)){if(in==null)throw new IOException("Missing packaged normalization source: "+name);return in.readAllBytes();}}
    private static Map<String,Object> profile()throws IOException{return object(SimpleJson.parse(new String(resource("SOURCE-PROFILES.json"),StandardCharsets.UTF_8)),"normalization source profile");}
    private static void sources(Path root,boolean compare)throws IOException{var files=new LinkedHashMap<>(object(profile().get("files"),"source pins"));files.put("SOURCE-PROFILES.json",Map.of("sha256",SeuratDifferentialRuntime.sha(resource("SOURCE-PROFILES.json"))));for(var e:files.entrySet()){if(!e.getKey().matches("[A-Za-z0-9._-]+"))throw new IOException("Unsafe normalization source name");byte[] bytes=resource(e.getKey());if(!SeuratDifferentialRuntime.sha(bytes).equals(object(e.getValue(),"source pin").get("sha256")))throw new IOException("Packaged normalization source mismatch");Path p=root.resolve("source/"+e.getKey());if(compare){if(!Arrays.equals(bytes,Files.readAllBytes(p)))throw new IOException("Captured normalization source differs");}else{Files.createDirectories(p.getParent());Files.write(p,bytes,StandardOpenOption.CREATE_NEW);}}}
    private static long capacity(Path root,long max)throws IOException{long total=0;for(long n:SeuratDifferentialRuntime.footprint(root).values()){if(n>max-total)throw new IOException("Complete normalization capture exceeds output capacity");total+=n;}return total;}
    private static void check(){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Native normalization interrupted");}
    private static String number(double v){return Double.isNaN(v)?"NaN":v==Double.POSITIVE_INFINITY?"Inf":v==Double.NEGATIVE_INFINITY?"-Inf":Double.toString(v);}
    private static String warningText(String state,List<String>warnings){return "# NATIVE NORMALIZATION: "+state+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action: "+ACTION+"\n";}
    private static void reject(Path root,Exception failure)throws IOException{var state=read(root.resolve("analysis-status.json"));state.put("status","FAIL2_PUBLISHED_VERIFICATION_FAILED");state.put("results_admitted",false);state.put("error",failure.toString());json(root.resolve("analysis-status.json"),state);var manifest=read(root.resolve("manifest.json"));manifest.put("analysis_status",state.get("status"));manifest.put("results_admitted",false);json(root.resolve("manifest.json"),manifest);json(root.resolve("COMPLETED.json"),Map.of("status",state.get("status"),"results_admitted",false));Files.writeString(root.resolve("WARNINGS.md"),"# FAIL2 — NO NORMALIZATION RESULT ADMITTED\n\n"+failure+"\n\nRequired action: "+ACTION+"\n\n"+Files.readString(root.resolve("WARNINGS.md")));SignacPeaksCli.seal(root);}
    private static void emit(PrintStream out,String s){out.writeBytes((s+"\n").getBytes(StandardCharsets.UTF_8));}
    private static final class Budget {final long max;long used;Budget(Path root,long max,boolean compare)throws IOException{this.max=max;used=capacity(root,max);}void add(long n)throws IOException{if(n>max-used)throw new IOException("Complete normalization output byte capacity exceeded");used+=n;}}
    private static final class Table implements AutoCloseable {final BufferedReader input;final OutputStream output;final Budget budget;Table(Path p,boolean compare,Budget budget)throws IOException{this.budget=budget;input=compare?SeuratDifferentialInputs.reader(p):null;output=compare?null:new BufferedOutputStream(Files.newOutputStream(p,StandardOpenOption.CREATE_NEW));}void row(String...values)throws IOException{var s=new StringWriter();FollowupSupport.row(s,values);line(s.toString());}void line(String s)throws IOException{check();if(input!=null){if(!s.substring(0,s.length()-1).equals(SeuratDifferentialInputs.line(input)))throw new IOException("Published native normalization/selection differs from replay");}else{byte[] bytes=s.getBytes(StandardCharsets.UTF_8);budget.add(bytes.length);output.write(bytes);}}public void close()throws IOException{if(input!=null)try{if(SeuratDifferentialInputs.line(input)!=null)throw new IOException("Extra normalization output rows");}finally{input.close();}else output.close();}}
}
